        }
        ASSERT_TRUE(executor->runNext());
        EXPECT_TRUE(called);
        EXPECT_EQ(executor->pendingCount(), 1u);
        EXPECT_EQ(pool->refCount(block), 2u);
        EXPECT_EQ(executor->runAll(), 1u);
        EXPECT_EQ(pool->refCount(block), 1u);
    }
    backend.shutdown();
    pool->decRef(block);
}

